INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — WACC with three capital components
(4, 'Capital Structure and Valuation', 'Redcliff Industries has $3,000,000 in debt at 7% interest, $2,000,000 in preferred stock with a 9% dividend rate, and $5,000,000 in common equity with a required return of 13%. The corporate tax rate is 25%. What is Redcliff''s weighted average cost of capital?', '["9.88%", "10.40%", "10.88%", "11.50%"]'::jsonb, 0, 'Under corporate finance principles consistent with ASC 820 fair value measurement, WACC is computed as the weighted sum of each component''s after-tax cost. Debt: (3M/10M) × 7% × (1 − 0.25) = 1.575%; preferred: (2M/10M) × 9% = 1.80%; equity: (5M/10M) × 13% = 6.50%. Total WACC = 9.875%, approximately 9.88%. Choice B (10.40%) incorrectly omits the tax shield on debt, using the full 7% cost: 2.10% + 1.80% + 6.50% = 10.40%.', 'medium', 2),

-- Q2: medium / L2 — Cost of equity via DDM
(4, 'Capital Structure and Valuation', 'Thornbury Corp. has a current stock price of $64 per share. The company expects to pay a dividend of $3.84 next year, and analysts forecast a perpetual dividend growth rate of 5%. Using the dividend discount model, what is Thornbury''s cost of equity?', '["10.5%", "11.0%", "9.0%", "12.0%"]'::jsonb, 1, 'Under the Gordon Growth Model (DDM), the cost of equity equals (D1 / P0) + g. Here, ($3.84 / $64) + 0.05 = 0.06 + 0.05 = 0.11, or 11.0%. This model is consistent with valuation frameworks referenced in ASC 820-10-35. Choice A (10.5%) results from using the current dividend of $3.52 instead of the expected next-year dividend D1, failing to grow the dividend forward one period.', 'medium', 2),

-- Q3: easy / L2 — CAPM cost of equity calculation
(4, 'Capital Structure and Valuation', 'Clearwater Logistics has a beta of 1.3. The risk-free rate is 4% and the expected market return is 10%. Using CAPM, what is Clearwater''s cost of equity?', '["11.0%", "11.8%", "17.0%", "10.0%"]'::jsonb, 1, 'Under the Capital Asset Pricing Model, cost of equity = Rf + β × (Rm − Rf) = 4% + 1.3 × (10% − 4%) = 4% + 7.8% = 11.8%. This systematic risk pricing is consistent with ASC 820-10-55 fair value estimation guidance. Choice A (11.0%) incorrectly uses a market risk premium of approximately 5.4% rather than the correct 6.0%.', 'easy', 2),

-- Q4: hard / L3 — Leverage effect on EPS volatility analysis
(4, 'Capital Structure and Valuation', 'Stratton Manufacturing (all-equity, 600,000 shares) and Waverly Industries ($12,000,000 debt at 6.5%, 350,000 shares) both have EBIT of $4,200,000 and a 25% tax rate. If EBIT declines 15% to $3,570,000, analyze the percentage decline in EPS for each firm and identify which experiences the greater amplification effect.', '["Stratton EPS falls 15.0%; Waverly EPS falls 20.8%", "Stratton EPS falls 15.0%; Waverly EPS falls 15.0%", "Stratton EPS falls 20.8%; Waverly EPS falls 15.0%", "Stratton EPS falls 12.5%; Waverly EPS falls 20.8%"]'::jsonb, 0, 'Financial leverage amplifies earnings changes as described in corporate finance theory consistent with ASC 470 debt guidance. Stratton: original EPS = ($4.2M × 0.75) / 600K = $5.25; new EPS = ($3.57M × 0.75) / 600K = $4.4625; decline = 15.0%. Waverly: interest = $780K; original EPS = (($4.2M − $780K) × 0.75) / 350K = $7.33; new EPS = (($3.57M − $780K) × 0.75) / 350K = $5.81; decline = 20.8%. Choice B ignores the leverage amplification entirely.', 'hard', 3),

-- Q5: medium / L3 — Effect of rising interest rates on WACC components
(4, 'Capital Structure and Valuation', 'Ridgemont Holdings has a target capital structure of 45% debt and 55% equity, with current WACC of 9.5%. If market interest rates increase by 200 basis points, raising the after-tax cost of debt from 4.5% to 6.5% and the cost of equity from 13% to 14.5%, what is the most likely effect on Ridgemont''s WACC?', '["WACC increases to approximately 10.88%", "WACC increases to approximately 11.50%", "WACC decreases because the tax shield becomes more valuable", "WACC remains unchanged because debt and equity effects offset"]'::jsonb, 0, 'Under WACC analysis consistent with ASC 820 fair value principles, the new WACC = (0.45 × 6.5%) + (0.55 × 14.5%) = 2.925% + 7.975% = 10.90%, approximately 10.88% with rounding. Rising rates increase both debt and equity costs, pushing WACC higher. Choice C incorrectly assumes the tax shield growth outweighs the cost increases, but the shield only reduces the pre-tax rate — it does not eliminate the rise.', 'medium', 3),

-- Q6: easy / L1 — Definition of systematic risk
(4, 'Capital Structure and Valuation', 'What type of risk does beta measure in the Capital Asset Pricing Model?', '["Systematic risk", "Unsystematic risk", "Credit risk", "Liquidity risk"]'::jsonb, 0, 'Under the CAPM framework consistent with ASC 820-10-55, beta measures systematic (market) risk — the sensitivity of a security''s returns to overall market movements. Systematic risk cannot be diversified away. Choice B (unsystematic risk) is incorrect because unsystematic risk is firm-specific and can be eliminated through diversification, so it is not priced by CAPM.', 'easy', 1),

-- Q7: medium / L2 — Degree of financial leverage calculation
(4, 'Capital Structure and Valuation', 'Prescott Industries reports EBIT of $3,600,000 and interest expense of $900,000 for the fiscal year ended December 31, 2025. Calculate Prescott''s degree of financial leverage.', '["1.25", "1.33", "4.00", "0.75"]'::jsonb, 1, 'The degree of financial leverage (DFL) equals EBIT / (EBIT − Interest) = $3,600,000 / ($3,600,000 − $900,000) = $3,600,000 / $2,700,000 = 1.33. This measure quantifies how operating income changes translate to earnings changes, consistent with leverage analysis under ASC 470. Choice A (1.25) results from incorrectly subtracting only $720,000 in interest, a common error when misreading the interest expense figure.', 'medium', 2),

-- Q8: easy / L1 — M-M Proposition I without taxes
(4, 'Capital Structure and Valuation', 'What does Modigliani-Miller Proposition I state in a world without taxes or bankruptcy costs?', '["Firm value is independent of its capital structure", "Firm value increases with more debt", "Firm value decreases with more debt", "Firm value equals the present value of its tax shields"]'::jsonb, 0, 'Modigliani-Miller Proposition I (1958), foundational to corporate finance theory referenced in ASC 820 valuation contexts, states that in a frictionless market without taxes, bankruptcy costs, or asymmetric information, total firm value is unaffected by how the firm is financed. Choice B is incorrect because increased firm value from debt only arises under M-M with taxes, where the interest tax shield creates additional value.', 'easy', 1),

-- Q9: easy / L1 — Definition of cost of preferred stock
(4, 'Capital Structure and Valuation', 'How is the cost of preferred stock calculated?', '["Annual preferred dividend divided by the net issuance price", "Annual preferred dividend divided by par value", "Coupon rate multiplied by one minus the tax rate", "Risk-free rate plus beta times the market risk premium"]'::jsonb, 0, 'The cost of preferred stock equals Dp / Pp, where Dp is the annual preferred dividend and Pp is the net price received from issuance. Unlike debt, preferred dividends are not tax-deductible, so no tax adjustment applies. This is consistent with valuation principles under ASC 480-10. Choice B is incorrect because using par value ignores market pricing; the relevant denominator is the net proceeds, not the stated par.', 'easy', 1),

-- Q10: easy / L2 — After-tax cost of debt
(4, 'Capital Structure and Valuation', 'Birchwood Enterprises issues bonds with a coupon rate of 8% at par. The corporate tax rate is 21%. What is Birchwood''s after-tax cost of debt?', '["8.00%", "6.32%", "6.00%", "7.32%"]'::jsonb, 1, 'The after-tax cost of debt = coupon rate × (1 − tax rate) = 8% × (1 − 0.21) = 8% × 0.79 = 6.32%. The tax deductibility of interest payments reduces the effective cost, as recognized under IRC Section 163 and reflected in ASC 740 income tax guidance. Choice A (8.00%) is the pre-tax cost and fails to account for the interest tax shield.', 'easy', 2),

-- Q11: easy / L1 — Pecking order theory definition
(4, 'Capital Structure and Valuation', 'Which theory predicts that firms prefer internal financing over external financing due to information asymmetry?', '["Pecking order theory", "Static trade-off theory", "Agency theory", "Signaling theory"]'::jsonb, 0, 'The pecking order theory (Myers and Majluf, 1984), referenced in corporate finance contexts related to ASC 505 equity disclosures, predicts firms prefer internal funds first, then debt, then equity — because external financing signals information asymmetry and adverse selection costs. Choice B (static trade-off theory) is incorrect because it focuses on balancing the tax benefits of debt against bankruptcy costs, not financing preferences driven by information asymmetry.', 'easy', 1),

-- Q12: hard / L4 — Evaluate optimal capital structure with competing factors
(4, 'Capital Structure and Valuation', 'Fairhaven Energy (current D/E ratio 0.3, WACC 10.2%) is evaluating raising leverage to D/E of 1.0. The CFO projects the after-tax cost of debt will rise from 4% to 5.5%, cost of equity from 12% to 16%, and the probability of financial distress will increase from 2% to 18%. Evaluate whether Fairhaven should adopt the higher leverage ratio.', '["No — the WACC increases to 10.75% and distress risk rises sharply, destroying value", "Yes — the larger tax shield more than compensates for higher distress costs", "Yes — higher leverage always increases firm value under M-M with taxes", "No — the cost of equity decreases with leverage under M-M Proposition II"]'::jsonb, 0, 'Under the static trade-off theory consistent with ASC 470 and ASC 820, optimal leverage balances tax shields against financial distress costs. At D/E = 1.0 (50/50), new WACC = (0.50 × 5.5%) + (0.50 × 16%) = 10.75%, exceeding the current 10.2%. Combined with distress probability surging from 2% to 18%, the incremental tax benefit is dominated by rising equity costs and distress risk. Choice B ignores that distress costs erode the tax shield benefit at high leverage levels.', 'hard', 4),

-- Q13: medium / L3 — Impact of share repurchase on capital structure ratios
(4, 'Capital Structure and Valuation', 'Northgate Corp. has total equity of $20,000,000, total debt of $10,000,000, and 2,000,000 shares outstanding at $10 per share. Northgate announces a $4,000,000 share repurchase financed entirely by new debt. Analyze the effect on the debt-to-equity ratio.', '["D/E increases from 0.50 to 0.875", "D/E increases from 0.50 to 0.75", "D/E decreases from 0.50 to 0.40", "D/E remains at 0.50"]'::jsonb, 0, 'Under ASC 505-30 (treasury stock), a debt-financed repurchase simultaneously increases debt and decreases equity. New debt = $10M + $4M = $14M; new equity = $20M − $4M = $16M; new D/E = $14M / $16M = 0.875. The original D/E was $10M / $20M = 0.50. Choice B (0.75) incorrectly keeps equity unchanged at $20M, computing $14M/$20M, ignoring that the repurchase reduces equity by the buyback amount.', 'medium', 3),

-- Q14: medium / L2 — Enterprise value to equity value per share
(4, 'Capital Structure and Valuation', 'Crestline Analytics has an enterprise value of $85,000,000, total debt of $22,000,000, cash of $7,000,000, and 4,000,000 shares outstanding. What is the implied equity value per share?', '["$17.50", "$15.75", "$21.25", "$20.50"]'::jsonb, 0, 'Enterprise value equals equity value plus net debt. Equity value = EV − debt + cash = $85M − $22M + $7M = $70M. Per share = $70M / 4M shares = $17.50. This is consistent with valuation frameworks under ASC 820-10-35. Choice B ($15.75) incorrectly subtracts cash instead of adding it, computing ($85M − $22M − $7M) / 4M = $14M, which is a common sign error.', 'medium', 2),

-- Q15: medium / L2 — Hamada equation levered beta
(4, 'Capital Structure and Valuation', 'Oakmont Precision has an unlevered beta of 0.9, a debt-to-equity ratio of 0.7, and a tax rate of 25%. Using the Hamada equation, what is Oakmont''s levered beta?', '["1.37", "1.53", "1.18", "0.90"]'::jsonb, 0, 'The Hamada equation states βL = βU × [1 + (1 − T) × (D/E)] = 0.9 × [1 + (1 − 0.25) × 0.7] = 0.9 × [1 + 0.525] = 0.9 × 1.525 = 1.3725, approximately 1.37. This framework for decomposing systematic risk is consistent with ASC 820 fair value estimation. Choice B (1.53) incorrectly omits the tax adjustment, computing 0.9 × (1 + 0.7) = 1.53.', 'medium', 2),

-- Q16: hard / L4 — Evaluate DDM vs CAPM for cost of equity
(4, 'Capital Structure and Valuation', 'Hargrove Industries'' CFO computes cost of equity using two methods. The DDM yields 11.2% (D1 = $2.80, P0 = $40, g = 4.2%). The CAPM yields 13.5% (Rf = 3.5%, β = 1.25, MRP = 8%). The two estimates differ by 230 basis points. Evaluate which model is more reliable given that Hargrove''s dividend payout has been erratic over the past five years.', '["CAPM is more reliable because erratic dividends undermine the DDM''s constant-growth assumption", "DDM is more reliable because it uses market price directly", "Both are equally reliable and should be averaged", "Neither model is reliable when estimates diverge by more than 200 basis points"]'::jsonb, 0, 'Under valuation guidance consistent with ASC 820-10-35, model selection depends on input reliability. The DDM requires a stable, predictable growth rate; erratic dividends violate the constant-growth assumption, making CAPM preferable when market data (beta, risk-free rate) is observable. Choice B is incorrect because while DDM does use market price, the model''s validity depends on dividend stability — not merely the use of a market input.', 'hard', 4),

-- Q17: easy / L1 — Definition of financial distress costs
(4, 'Capital Structure and Valuation', 'What are financial distress costs in the context of capital structure theory?', '["Direct and indirect costs incurred when a firm has difficulty meeting debt obligations", "The tax benefits lost when a firm uses too little debt", "The cost of issuing new equity to replace maturing debt", "The agency costs between shareholders and managers"]'::jsonb, 0, 'Financial distress costs, central to the static trade-off theory and referenced in ASC 450-20 (loss contingencies), include both direct costs (legal fees, court costs) and indirect costs (lost customers, supplier hesitancy, management distraction) that arise when a firm struggles to service its debt. Choice D (agency costs) is a distinct concept involving conflicts between stakeholders, not the costs triggered by potential insolvency.', 'easy', 1),

-- Q18: easy / L1 — Signaling theory and equity issuance
(4, 'Capital Structure and Valuation', 'Under signaling theory, what typically happens to a company''s stock price when it announces a new equity issuance?', '["The stock price typically declines", "The stock price typically increases", "The stock price remains unchanged", "The stock price becomes more volatile but with no directional bias"]'::jsonb, 0, 'Signaling theory (Myers and Majluf, 1984), relevant to ASC 505-10 equity disclosure, predicts that managers issue equity when they believe shares are overvalued. Investors interpret the issuance as a negative signal, causing the stock price to decline. Choice B is incorrect because a price increase would only occur if the market interpreted the issuance as a positive investment opportunity, which contradicts the asymmetric information premise of signaling theory.', 'easy', 1),

-- Q19: hard / L4 — Recommend financing choice under multiple constraints
(4, 'Capital Structure and Valuation', 'Pinnacle Biotech needs $15,000,000 for a clinical trial. Options: (A) issue 10-year bonds at 7.5%, (B) issue preferred stock at 8.5%, or (C) issue common equity at current price of $30/share. Pinnacle has $2,000,000 in NOL carryforwards, a current D/E ratio of 1.8, and the CFO expects profitability in 3 years. Recommend the best financing option.', '["Issue preferred stock — NOLs eliminate the debt tax shield advantage and leverage is already high", "Issue bonds — debt is always cheapest due to the tax shield", "Issue common equity — it eliminates all financial risk", "Issue bonds — the NOL carryforwards enhance the tax shield"]'::jsonb, 0, 'Under the trade-off theory and ASC 740-10-25 (deferred tax assets), NOL carryforwards mean Pinnacle pays no current taxes, eliminating the debt tax shield advantage for years. With D/E already at 1.8, additional debt raises distress risk substantially. Preferred stock provides fixed-cost capital without increasing leverage ratios or diluting common equity control. Choice B is incorrect because the tax shield benefit is nullified while NOLs offset taxable income, removing debt''s primary cost advantage.', 'hard', 4),

-- Q20: medium / L3 — Analyze effect of debt covenant violation on capital decisions
(4, 'Capital Structure and Valuation', 'Redstone Manufacturing has a debt covenant requiring a maximum D/E ratio of 1.5. Current debt is $18,000,000 and equity is $12,000,000 (D/E = 1.5). Redstone needs $3,000,000 for new equipment. Analyze which financing source would avoid a covenant violation.', '["Issue common equity to fund the purchase", "Finance with a new term loan", "Use a 50/50 mix of debt and equity", "Lease the equipment as an operating lease under ASC 842"]'::jsonb, 0, 'Under ASC 470-10 and covenant analysis, Redstone is at its D/E ceiling of 1.5. New debt of $3M would push D/E to $21M/$12M = 1.75, violating the covenant. Issuing $3M equity changes D/E to $18M/$15M = 1.20, staying within limits. Choice D may seem viable, but under ASC 842, operating leases create right-of-use assets and lease liabilities that may still affect leverage ratios depending on covenant definitions.', 'medium', 3),

-- Q21: medium / L3 — Effect of stock split on valuation metrics
(4, 'Capital Structure and Valuation', 'Sagebrush Holdings has 1,000,000 shares outstanding at $80 per share, total equity of $40,000,000, and earnings of $8,000,000. After a 2-for-1 stock split, analyze the effect on earnings per share, book value per share, and total market capitalization.', '["EPS halves to $4.00, book value per share halves to $20.00, market cap unchanged at $80,000,000", "EPS unchanged at $8.00, book value per share unchanged, market cap doubles", "EPS halves to $4.00, book value per share unchanged, market cap halves", "EPS unchanged, book value per share halves, market cap unchanged"]'::jsonb, 0, 'Under ASC 505-20 (stock splits), a 2-for-1 split doubles shares to 2,000,000 while total equity, earnings, and market cap remain unchanged. EPS = $8M / 2M = $4.00 (halved from $8.00). Book value per share = $40M / 2M = $20.00 (halved from $40.00). Market cap = 2M × $40 = $80M (unchanged). Choice B incorrectly assumes per-share metrics remain constant, which would imply value creation from a purely cosmetic transaction.', 'medium', 3),

-- Q22: medium / L3 — Effect of tax rate change on WACC
(4, 'Capital Structure and Valuation', 'Brookfield Corp. has 40% debt (pre-tax cost 6%) and 60% equity (cost 14%). Currently the tax rate is 21%, yielding WACC of 10.30%. Congress enacts a tax rate increase to 28%. Analyze how this change affects Brookfield''s WACC, assuming the cost of equity and pre-tax cost of debt remain constant.', '["WACC decreases to 10.13% because the larger tax shield reduces the after-tax cost of debt", "WACC increases to 10.70% because higher taxes reduce after-tax cash flows", "WACC remains at 10.30% because debt and equity effects offset", "WACC decreases to 9.50% because the tax shield doubles"]'::jsonb, 0, 'Under WACC computation consistent with ASC 740, the after-tax cost of debt = 6% × (1 − 0.28) = 4.32%, down from 6% × (1 − 0.21) = 4.74%. New WACC = (0.40 × 4.32%) + (0.60 × 14%) = 1.728% + 8.40% = 10.13%. The higher tax rate increases the debt tax shield, lowering WACC slightly. Choice B confuses the effect on firm cash flows with the effect on the discount rate; WACC falls even though after-tax income declines.', 'medium', 3),

-- Q23: hard / L4 — Evaluate project acceptance with risk-adjusted discount rate
(4, 'Capital Structure and Valuation', 'Mercer Capital evaluates two projects for Ashford Holdings (WACC 10%). Project Alpha has expected returns of 12% and a beta of 1.8 (risk-adjusted rate 15%). Project Beta has expected returns of 11% and a beta of 0.6 (risk-adjusted rate 7%). Evaluate which project(s) should be accepted and explain why using WACC alone could lead to incorrect decisions.', '["Accept only Beta — its return exceeds its risk-adjusted rate; Alpha''s return falls below its risk-adjusted rate", "Accept both — both exceed the firm''s WACC of 10%", "Accept only Alpha — it has the higher absolute return", "Reject both — neither exceeds the risk-adjusted rate"]'::jsonb, 0, 'Under project evaluation consistent with ASC 820 fair value hierarchy, each project should be evaluated against its own risk-adjusted discount rate, not the firm''s overall WACC. Alpha: 12% < 15% risk-adjusted rate (reject). Beta: 11% > 7% risk-adjusted rate (accept). Choice B is incorrect because using WACC alone ignores project-specific risk; Alpha appears profitable at 10% but destroys value relative to its true risk level.', 'hard', 4),

-- Q24: medium / L3 — Impact of capital structure shift on beta
(4, 'Capital Structure and Valuation', 'Westbrook Technologies has a levered beta of 1.6, a D/E ratio of 1.0, and a tax rate of 25%. The company announces a plan to reduce leverage to a D/E of 0.4 by retiring debt with an equity offering. Analyze the approximate effect on the firm''s levered beta after restructuring.', '["Beta decreases to approximately 1.12", "Beta increases to approximately 2.00", "Beta remains at 1.60 because business risk is unchanged", "Beta decreases to approximately 0.91"]'::jsonb, 0, 'Using the Hamada equation consistent with ASC 820 risk assessment, first find unlevered beta: βU = βL / [1 + (1 − T)(D/E)] = 1.6 / [1 + 0.75 × 1.0] = 1.6 / 1.75 = 0.914. New levered beta: βL = 0.914 × [1 + 0.75 × 0.4] = 0.914 × 1.30 = 1.12. Reducing leverage decreases the equity holders'' systematic risk exposure. Choice C incorrectly assumes beta depends only on business risk, ignoring the financial risk component that changes with leverage.', 'medium', 3),

-- Q25: medium / L2 — Equity value from free cash flow to equity
(4, 'Capital Structure and Valuation', 'Aldridge Consulting generates free cash flow to equity (FCFE) of $6,500,000 annually. Analysts expect FCFE to grow at 3% indefinitely. The cost of equity is 11%. Using the single-stage FCFE model, what is the total equity value of Aldridge?', '["$81,250,000", "$83,718,750", "$59,090,909", "$72,222,222"]'::jsonb, 1, 'The single-stage FCFE model values equity as FCFE₁ / (ke − g) = ($6,500,000 × 1.03) / (0.11 − 0.03) = $6,695,000 / 0.08 = $83,718,750. This perpetuity growth model is consistent with ASC 820-10-35 income approach guidance. Choice A ($81,250,000) incorrectly uses current-year FCFE ($6.5M / 0.08) without growing it forward one period, a common timing error in DCF models.', 'medium', 2),

-- Q26: medium / L2 — EV/EBITDA multiple valuation
(4, 'Capital Structure and Valuation', 'Windgate Technologies reports EBITDA of $14,000,000. Comparable public companies trade at a median EV/EBITDA multiple of 8.5x. Windgate has $25,000,000 in debt and $5,000,000 in cash. What is the implied equity value?', '["$99,000,000", "$119,000,000", "$94,000,000", "$114,000,000"]'::jsonb, 0, 'Under the market approach consistent with ASC 820-10-35, enterprise value = EBITDA × multiple = $14M × 8.5 = $119M. Equity value = EV − debt + cash = $119M − $25M + $5M = $99M. The bridge from EV to equity requires subtracting debt and adding back cash holdings. Choice C ($94M) incorrectly subtracts both debt and cash ($119M − $25M = $94M), failing to add cash back to equity holders.', 'medium', 2),

-- Q27: easy / L2 — Simple WACC two-component calculation
(4, 'Capital Structure and Valuation', 'Maplewood Corp. has a capital structure of 35% debt and 65% equity. The after-tax cost of debt is 3.8% and the cost of equity is 11.5%. What is Maplewood''s WACC?', '["8.81%", "7.65%", "9.33%", "10.08%"]'::jsonb, 0, 'WACC = (wd × kd) + (we × ke) = (0.35 × 3.8%) + (0.65 × 11.5%) = 1.33% + 7.475% = 8.805%, approximately 8.81%. This weighted average approach is consistent with ASC 820-10-35 discount rate guidance. Choice B (7.65%) results from swapping the weights, incorrectly applying the equity weight to debt cost and vice versa.', 'easy', 2),

-- Q28: hard / L4 — Evaluate lease vs buy considering capital structure impact
(4, 'Capital Structure and Valuation', 'Ironclad Manufacturing (D/E = 1.2, covenant max = 1.5) must acquire $8,000,000 equipment. Option A: purchase with a 5-year loan at 6%. Option B: 5-year finance lease at an implicit rate of 6.5%. Current debt is $36,000,000 and equity is $30,000,000. Evaluate which option better serves Ironclad''s capital structure constraints under ASC 842.', '["Neither option is clearly better — under ASC 842 both the loan and finance lease increase reported liabilities and raise D/E above the covenant maximum", "Purchase with a loan is better because loans have a lower interest rate", "Finance lease is better because leases do not appear on the balance sheet", "Purchase with a loan is better because only operating leases create liabilities under ASC 842"]'::jsonb, 0, 'Under ASC 842-20, finance leases create a right-of-use asset and lease liability on the balance sheet, similar to a purchase loan. Adding $8M via either method raises debt to approximately $44M, pushing D/E to $44M/$30M = 1.47 (dangerously close to the 1.5 covenant). Neither option provides a clear capital structure advantage. Choice C is incorrect because ASC 842 requires both finance and operating leases to be recognized on the balance sheet.', 'hard', 4),

-- Q29: medium / L3 — Effect of dividend increase on cost of equity
(4, 'Capital Structure and Valuation', 'Hartwell Industries currently pays a $2.00 dividend (stock price $50, growth rate 4%, DDM cost of equity = 8%). The board approves a dividend increase to $2.50 per share. Assuming the growth rate and required return remain constant, analyze the most likely effect on Hartwell''s stock price.', '["Stock price increases to $62.50 because the higher dividend raises the present value of future cash flows", "Stock price decreases because higher dividends reduce retained earnings", "Stock price remains at $50 because dividends are irrelevant under M-M", "Stock price increases to $52.50 — only the $2.50 increment is added"]'::jsonb, 0, 'Under the Gordon Growth Model consistent with ASC 820-10-35, P0 = D1 / (ke − g). With the new dividend of $2.50 and unchanged ke (8%) and g (4%): next year D1 = $2.50 × 1.04 = $2.60; P0 = $2.60 / (0.08 − 0.04) = $2.60 / 0.04 = $65.00 — or using the current dividend: $2.50 / (0.08 − 0.04) = $62.50. The higher dividend raises intrinsic value. Choice C assumes M-M dividend irrelevance, which only holds in a frictionless, tax-free market.', 'medium', 3),

-- Q30: medium / L3 — Analyze reinvestment rate and sustainable growth
(4, 'Capital Structure and Valuation', 'Ashland Corp. has ROE of 18% and pays out 40% of earnings as dividends. The CFO proposes cutting the payout ratio to 25% to fund expansion. Analyze the effect of this change on Ashland''s sustainable growth rate.', '["Sustainable growth rate increases from 10.8% to 13.5%", "Sustainable growth rate decreases because lower dividends reduce investor demand", "Sustainable growth rate remains unchanged because ROE is constant", "Sustainable growth rate increases from 7.2% to 13.5%"]'::jsonb, 0, 'The sustainable growth rate equals ROE × retention ratio. Original: 18% × (1 − 0.40) = 18% × 0.60 = 10.8%. Proposed: 18% × (1 − 0.25) = 18% × 0.75 = 13.5%. This reinvestment-driven growth analysis is consistent with valuation principles under ASC 820. Choice D (7.2% to 13.5%) incorrectly computes the original rate using the payout ratio (18% × 0.40 = 7.2%) instead of the retention ratio.', 'medium', 3)
;

COMMIT;
